input.content:
:root {
  --bg: #0b0f14;
  --panel: #121a24;
  --surface: #172130;
  --text: #e8eef6;
  --muted: #94a3b8;
  --accent: #7c3aed;
  --accent2: #06b6d4;
  --danger: #ef4444;
  --ok: #22c55e;
  --warn: #f59e0b;
  --border: #243040;
  --ring: #7c3aed;
  --font: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Ubuntu, Cantarell, Helvetica Neue, Arial, "Noto Sans", sans-serif;
}

* { box-sizing: border-box; }
html, body {
  height: 100%;
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  overflow-x: hidden;
}
body.dark { filter: none; }
body.light { --bg:#f1f5f9; --panel:#ffffff; --surface:#eef2f7; --text:#0f172a; --muted:#475569; --border:#cbd5e1; filter:invert(0); }

/* ---------- shell ---------- */
.shell {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 18px;
  background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 40;
  backdrop-filter: blur(6px);
}
.brand { display: flex; align-items: center; gap: 9px; font-weight: 700; letter-spacing: -0.4px; }
.mark {
  width: 28px; height: 28px; border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), var(--accent2));
  display: grid; place-items: center; font-size: 17px; font-weight: 800;
}
.sub { font-size: 11px; color: var(--muted); display: block; margin-top: -2px; }
.chips { display: flex; gap: 8px; flex: 1; }
.chip {
  font-size: 11px; padding: 3px 9px; border-radius: 12px; border: 1px solid var(--border);
  background: var(--surface); color: var(--muted);
}
.chip-on { color: #06b6d4; border-color: rgba(6,182,212,0.35); background: rgba(6,182,212,0.08); }
.chip-ok { color: var(--ok); border-color: rgba(34,197,94,0.35); background: rgba(34,197,94,0.08); }
.chip-warn { color: var(--warn); border-color: rgba(245,158,11,0.35); background: rgba(245,158,11,0.08); }
.actions { display: flex; gap: 8px; }

/* ---------- buttons ---------- */
.btn {
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
  padding: 7px 14px; border-radius: 10px; font-size: 13px; cursor: pointer;
  font-family: inherit; font-weight: 600; transition: transform .06s, border-color .2s, background .2s;
}
.btn:hover { border-color: var(--ring); background: #1e2a3c; }
.btn:active { transform: scale(0.97); }
.btn.btn-record { background: var(--danger); border-color: var(--danger); color: #fff; box-shadow: 0 0 0 0 rgba(239,68,68,0.4); }
.btn.btn-record.recording { animation: pulse 1.2s infinite; background: #b91c1c; border-color: #b91c1c; }
.btn.btn-play { background: var(--ok); border-color: var(--ok); color: #fff; }
.btn.btn-stop { background: var(--warn); border-color: var(--warn); color: #000; }
.btn.ghost { background: transparent; border-color: transparent; color: var(--muted); }
.btn.ghost:hover { color: var(--text); background: rgba(255,255,255,0.05); }
.btn.small { padding: 5px 11px; font-size: 12px; }
.btn.danger { background: transparent; color: var(--danger); border-color: var(--danger); }
.btn.danger:hover { background: rgba(239,68,68,0.15); }
.dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: #fff; margin-right: 7px; animation: blink 1.2s infinite; }
@keyframes blink { 0%,100% {opacity:.4} 50% {opacity:1} }
@keyframes pulse { 0%,100% {box-shadow: 0 0 0 0 rgba(239,68,68,0.4)} 50% {box-shadow: 0 0 0 10px rgba(239,68,68,0)} }

/* ---------- studio ---------- */
.studio { display: flex; height: calc(100vh - 56px); overflow: hidden; }
.sidebar {
  width: 220px; flex-shrink: 0; background: var(--panel);
  border-right: 1px solid var(--border); display: flex; flex-direction: column;
  padding: 16px 0;
}
.nav { display: flex; flex-direction: column; gap: 4px; padding: 0 12px; }
.nav-item {
  width: 100%; text-align: left; padding: 9px 12px; border-radius: 10px;
  border: none; background: transparent; color: var(--muted); font-size: 13.5px; cursor: pointer;
  display: flex; align-items: center; gap: 9px;
}
.nav-item:hover { background: rgba(255,255,255,0.05); color: var(--text); }
.nav-item.active { background: var(--accent); color: #fff; }
.footer-note { margin: 16px 12px; font-size: 11px; color: var(--muted); line-height: 1.5; }

main.panel { flex: 1; overflow-y: auto; padding: 22px 26px; display: none; }
main.panel.hidden { display: none; }
main.panel:not(.hidden) { display: block; }

.page-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.page-head h2 { margin: 0; font-size: 20px; letter-spacing: -0.3px; }

h2 { font-size: 17px; margin: 0 0 8px; color: var(--text); }
h3 { font-size: 15px; margin: 0 0 6px; }
h4 { font-size: 13px; margin: 0 0 5px; color: var(--text); }
p { margin: 0 0 10px; color: var(--muted); font-size: 13.5px; line-height: 1.55; }
.muted { color: var(--muted); }

.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 14px; }
.card {
  background: var(--panel); border: 1px solid var(--border); border-radius: 14px;
  padding: 16px; display: flex; flex-direction: column; gap: 8px;
}
.card h3 { color: var(--text); }
.recent { margin-top: 26px; border-top: 1px solid var(--border); padding-top: 14px; }

/* ---------- phone simulator ---------- */
.phone-toolbar { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.phone-title { font-weight: 700; color: var(--text); }
.phone-right { margin-left: auto; display: flex; gap: 8px; }
.device-wrap { position: relative; width: 100%; max-width: 430px; height: 760px; margin: 0 auto; }
.device {
  position: relative; width: 100%; height: 100%; border-radius: 34px;
  background: #0a0a0a; border: 12px solid #1a1a1a; box-shadow: 0 20px 60px rgba(0,0,0,0.6);
  overflow: hidden;
}
.sensor-bar { position: absolute; top: 16px; left: 50%; transform: translateX(-50%);
  width: 104px; height: 18px; border-radius: 9px; background: #1a1a1a; border: 1px solid #333;
  z-index: 2; display: flex; align-items: center; justify-content: center; gap: 5px; padding: 0 6px;
}
.sensor-bar::after { content:""; width: 5px; height: 5px; border-radius: 50%; background: #fff; box-shadow: 0 0 6px #fff; }
.screen { position: relative; width: 100%; height: 100%; background: #0f172a; overflow: hidden; }
.nav-bar { position: absolute; bottom: 0; left: 0; right: 0; height: 70px;
  background: linear-gradient(180deg, rgba(0,0,0,0.35), #000); display: flex; justify-content: center; align-items: center; gap: 26px;
  border-top: 1px solid rgba(255,255,255,0.06); z-index: 3;
}
.nav-btn { background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); color: #ddd;
  width: 44px; height: 44px; border-radius: 50%; cursor: pointer; font-size: 13px; display: grid; place-items: center;
}
.nav-btn:active { background: rgba(255,255,255,0.2); color: #fff; }
.overlay-canvas {
  position: absolute; inset: 0; pointer-events: none; border-radius: 34px;
  z-index: 5; background: transparent;
}
.draw-hud {
  position: absolute; bottom: 120px; left: 50%; transform: translateX(-50%);
  display: flex; gap: 8px; align-items: center; background: rgba(10,10,10,0.8);
  padding: 8px 12px; border-radius: 16px; border: 1px solid rgba(255,255,255,0.12); z-index: 6;
  pointer-events: auto; backdrop-filter: blur(6px);
}
.draw-swatch { width: 22px; height: 22px; border-radius: 50%; border: 2px solid #fff; cursor: pointer; display: inline-block; }
.draw-swatch:hover { transform: scale(1.15); }
.draw-label { font-size: 11px; color: #ccc; margin-right: 6px; }
.phone-hint { text-align: center; color: var(--muted); font-size: 12px; margin-top: 10px; min-height: 18px; }

/* ---------- macros ---------- */
.macro-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.macro-table-wrap { overflow: auto; border: 1px solid var(--border); border-radius: 12px; margin-top: 8px; }
.macro-table { width: 100%; border-collapse: collapse; font-size: 13px; background: var(--panel); }
.macro-table th, .macro-table td { border-bottom: 1px solid var(--border); padding: 10px 12px; text-align: left; color: var(--text); }
.macro-table th { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; }
.macro-table tr:hover td { background: rgba(255,255,255,0.03); }
.empty-state { color: var(--muted); text-align: center; padding: 26px; font-size: 13px; }
.editor-card { margin-top: 18px; background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 16px; }
.form-row { display: flex; flex-direction: column; gap: 5px; margin-bottom: 10px; }
.form-row label { font-size: 12px; color: var(--muted); font-weight: 600; }
.form-row input, .form-row textarea { background: #0b121c; border: 1px solid var(--border); color: var(--text);
  border-radius: 8px; padding: 8px 10px; font-size: 13px; font-family: inherit; }
.form-row textarea { font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace; resize: vertical; }
.form-actions { display: flex; gap: 8px; margin-top: 8px; }
.step-hint { font-size: 11px; color: var(--muted); margin-top: 8px; font-family: monospace; }

/* ---------- scripts ---------- */
.script-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 10px; }
.ghost-select { background: var(--surface); border: 1px solid var(--border); color: var(--text);
  border-radius: 8px; padding: 6px 10px; font-size: 13px; font-family: inherit; }
.script-editor-wrap { border: 1px solid var(--border); border-radius: 12px; background: #0b121c; margin-bottom: 12px; }
#script-editor { width: 100%; height: 230px; background: transparent; border: none; color: #d4d4d4;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace; font-size: 13px;
  padding: 14px; resize: vertical; outline: none; }
.script-doc { margin-top: 10px; }
.doc-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.doc-table td { border-bottom: 1px solid var(--border); padding: 7px 10px; vertical-align: top; }
.doc-table td:first-child { color: var(--accent2); font-family: monospace; white-space: nowrap; width: 34%; }
.script-output { margin-top: 10px; background: #0b121c; border: 1px solid var(--border); border-radius: 10px;
  padding: 10px 12px; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12.5px; color: #a5f3fc; min-height: 40px; max-height: 220px; overflow-y: auto; white-space: pre-wrap; }
.script-output .log-ok { color: #22c55e; }
.script-output .log-err { color: #ef4444; }
.script-output .log-info { color: var(--muted); }

/* ---------- recognition ---------- */
.rec-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 12px; }
.rec-actions select { background: var(--surface); border: 1px solid var(--border); color: var(--text);
  border-radius: 8px; padding: 6px 10px; font-size: 13px; font-family: inherit; }
.rec-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px; margin-bottom: 14px; }
.rec-card { background: var(--panel); border: 1px solid var(--border); border-radius: 12px; padding: 14px; }
.rec-result { margin-top: 8px; font-size: 12px; color: var(--muted); min-height: 18px; }
.rec-result .ok { color: #22c55e; font-weight: 700; }
.rec-hint { color: var(--muted); font-size: 12.5px; }

/* ---------- keyboard ---------- */
.kb-preview { border: 1px solid var(--border); border-radius: 12px; background: #0b121c; padding: 14px; margin-bottom: 12px; min-height: 130px; display: flex; align-items: center; justify-content: center; color: var(--muted); font-size: 13px; }
.kb-controls { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.kb-lang { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--muted); }
.kb-lang select { background: var(--surface); border: 1px solid var(--border); color: var(--text);
  border-radius: 8px; padding: 5px 9px; font-size: 13px; font-family: inherit; }
.kb-hint { color: var(--muted); font-size: 12px; }

/* clipboard */
.clip-toolbar { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 12px; }
.clip-toolbar input[type="text"] { flex: 1; min-width: 200px; background: #0b121c; border: 1px solid var(--border);
  color: var(--text); border-radius: 8px; padding: 8px 10px; font-size: 13px; }
.clip-list { display: flex; flex-direction: column; gap: 8px; }
.clip-item {
  background: var(--panel); border: 1px solid var(--border); border-radius: 10px; padding: 10px 12px;
  display: flex; justify-content: space-between; align-items: center; cursor: pointer;
}
.clip-item:hover { border-color: var(--ring); }
.clip-item .text { font-size: 13px; color: var(--text); max-width: 260px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.clip-item .meta { font-size: 11px; color: var(--muted); }
.clip-hint { color: var(--muted); font-size: 12px; }

/* settings */
.settings-list { display: flex; flex-direction: column; gap: 12px; margin-top: 10px; }
.setting { display: flex; align-items: center; justify-content: space-between; padding: 10px 12px;
  background: var(--panel); border: 1px solid var(--border); border-radius: 10px; }
.switch { position: relative; display: inline-block; width: 44px; height: 24px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; inset: 0; background: var(--border); border-radius: 24px; transition: .2s; }
.slider:before { position: absolute; content: ""; height: 16px; width: 16px; left: 4px; bottom: 4px;
  background: #fff; border-radius: 50%; transition: .2s; }
.switch input:checked + .slider { background: var(--accent); }
.switch input:checked + .slider:before { transform: translateX(20px); }
.settings-actions { display: flex; gap: 8px; margin-top: 18px; flex-wrap: wrap; }

/* ---------- keyboard overlay ---------- */
.kb-overlay {
  position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%);
  z-index: 1000; display: flex; flex-direction: column; gap: 8px; align-items: center;
  pointer-events: none;
}
.kb-overlay.hidden { display: none !important; }
.kb-handle { width: 34px; height: 34px; border-radius: 50%; background: rgba(20,26,36,0.9);
  border: 1px solid var(--border); color: #94a3b8; font-size: 18px; display: grid; place-items: center;
  cursor: grab; pointer-events: auto; user-select: none; }
.kb-handle:active { cursor: grabbing; }
.kb-window {
  background: rgba(12, 17, 27, 0.95); border: 1px solid var(--border); border-radius: 16px;
  padding: 10px; display: flex; flex-direction: column; gap: 8px; pointer-events: auto;
  box-shadow: 0 25px 80px rgba(0,0,0,0.7);
}
.kb-bar { display: flex; justify-content: space-between; align-items: center; }
.kb-btn {
  background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); color: #e8eef6;
  border-radius: 10px; font-size: 16px; font-weight: 700; cursor: pointer; font-family: inherit;
  width: 46px; height: 46px; display: grid; place-items: center;
}
.kb-btn:active { background: rgba(255,255,255,0.2); }
.kb-btn.kb-mic { width: 46px; height: 46px; border-radius: 50%; }
.kb-btn.kb-mic.listening { background: var(--danger); border-color: var(--danger); box-shadow: 0 0 0 0 rgba(239,68,68,0.4); animation: pulse 1.2s infinite; }
.kb-btn.kb-close { font-size: 20px; color: var(--muted); }
.kb-keys { display: grid; grid-template-columns: repeat(10, 1fr); gap: 6px; }
.kb-row { display: flex; gap: 6px; }
.kb-btn.kb-wide { flex: 1; }
.kb-btn.kb-space { flex: 2; }
.kb-btn.kb-del { width: 56px; }
.floating-actions { position: fixed; right: 20px; bottom: 88px; z-index: 950; display: flex; flex-direction: column; gap: 10px; pointer-events: auto; }
.floating-actions.hidden { display: none !important; }
.fab { width: 50px; height: 50px; border-radius: 50%; background: var(--accent); border: none; color: #fff;
  font-size: 19px; cursor: pointer; box-shadow: 0 8px 24px rgba(124,58,237,0.45); }
.fab:active { transform: scale(0.93); }
.mic-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--muted); margin-right: 6px; display: inline-block; }
.kb-mic.listening .mic-dot { background: #fff; animation: blink 1s infinite; }

/* toasts */
#toast-container { position: fixed; top: 70px; right: 16px; z-index: 200; display: flex; flex-direction: column; gap: 8px; pointer-events: none; }
.toast { background: rgba(15,23,35,0.95); border: 1px solid var(--border); color: #fff; padding: 9px 14px;
  border-radius: 10px; font-size: 12.5px; box-shadow: 0 10px 30px rgba(0,0,0,0.4); pointer-events: auto;
  animation: slideIn .3s ease; display: flex; align-items: center; gap: 8px; }
@keyframes slideIn { from { transform: translateX(120px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
@keyframes blink { 0%,100% {opacity:.5} 50% {opacity:1} }

/* mobile adjustments */
@media (max-width: 720px) {
  .studio { flex-direction: column; height: auto; }
  .sidebar { width: 100%; height: auto; border-right: none; border-bottom: 1px solid var(--border); padding: 8px 0; }
  .nav { flex-direction: row; overflow-x: auto; padding: 0 10px; gap: 6px; }
  .nav-item { white-space: nowrap; padding: 7px 10px; font-size: 12px; }
  main.panel { padding: 12px 14px; }
  header.shell { padding: 8px 12px; }
  .chips { display: none; }
  .device-wrap { max-width: 100%; height: 620px; }
}

/* Automa — Automation Studio (playable web demo)
   Implements: macro record/playback+save/edit, internal scripting,
   recognition (text/object/image/template) + tracking, draw-on-top,
   custom keyboard with mic, clipboard, simulated phone screen with apps.
*/

const STORAGE_KEY = 'automa_v1';
const SCREEN_W = 375;
const SCREEN_H = 812;

const state = {
  currentApp: 'home',
  settings: { wifi: true, bluetooth: false, accessibility: false, dark: false },
  notesText: '',
  clipboard: JSON.parse(localStorage.getItem(STORAGE_KEY + '.clipboard') || '[]'),
  macros: JSON.parse(localStorage.getItem(STORAGE_KEY + '.macros') || '[]'),
  selectedMacroId: null,
  recording: false,
  recordingSteps: [],
  playing: false,
  focusedId: null,
  focusedValue: '',
  overlayOn: false,
  drawMode: false,
  drawColor: '#ff4757',
  drawSize: 6,
  kbVisible: false,
  kbShift: false,
  kbLayout: 'en',
  micOn: false,
  recognition: null,
  trackingId: null,
  highlights: [],
  scriptText: '',
  lastToast: 0
};

// ---------------------------------------------------------------------------
// init
// ---------------------------------------------------------------------------
function init() {
  bindShell();
  bindPhoneNav();
  bindMacros();
  bindScripts();
  bindRecognition();
  bindKeyboard();
  bindClipboard();
  bindSettings();
  bindDraw();
  bindRecordPlay();
  loadStateIntoUI();
  renderScreen();
  renderMacroList();
  renderClipboard();
  renderKeyboardPreview();
  populateTrackSelect();
  log('Automa ready. Local-first automation studio.', 'info');
}

// ---------------------------------------------------------------------------
// shell / nav
// ---------------------------------------------------------------------------
function bindShell() {
  document.querySelectorAll('.nav-item').forEach(b => {
    b.addEventListener('click', () => openSection(b.dataset.sec));
  });
  const dark = document.getElementById('set-dark');
  if (localStorage.getItem(STORAGE_KEY + '.dark') === '1') {
    document.body.classList.add('light'); dark.checked = true;
  }
}
function openSection(sec) {
  document.querySelectorAll('.nav-item').forEach(b =>
    b.classList.toggle('active', b.dataset.sec === sec));
  document.querySelectorAll('main.panel').forEach(p =>
    p.classList.add('hidden'));
  document.getElementById('panel-' + sec).classList.remove('hidden');
  if (sec === 'phone') renderScreen();
  if (sec === 'macros') renderMacroList();
  if (sec === 'clipboard') renderClipboard();
  if (sec === 'recognition') populateTrackSelect();
  updateChips();
}
function toast(msg, kind = 'info') {
  const t = document.createElement('div');
  t.className = 'toast';
  t.innerHTML = '<span style="font-weight:700">' + kind.toUpperCase() + '</span> ' + escapeHtml(msg);
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 2600);
}
function updateChips() {
  document.getElementById('chip-overlay').textContent = 'OVERLAY: ' + (state.overlayOn ? 'on' : 'off');
  document.getElementById('chip-kb').textContent = 'KEYBOARD: ' + (state.kbVisible ? 'visible' : 'hidden');
  document.getElementById('chip-clip').textContent = 'CLIPBOARD: ' + state.clipboard.length;
  document.getElementById('chip-mic').textContent = 'MIC: ' + (state.micOn ? 'on' : 'off');
  document.getElementById('chip-mic').className = 'chip ' + (state.micOn ? 'chip-warn' : '');
  document.getElementById('chip-script').textContent = 'SCRIPT: ' + (state.playing ? 'running' : 'ready');
}
function escapeHtml(s) { return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":"&#39;"}[c])); }

// ---------------------------------------------------------------------------
// phone simulator
// ---------------------------------------------------------------------------
const screen = document.getElementById('screen');
const phoneTitle = document.getElementById('phone-title');
const kbToggle = document.getElementById('btn-kb-toggle');

function el(id, type, text, x, y, w, h, { desc = '', color = '', value = '', onclick } = {}) {
  const d = document.createElement('div');
  d.className = 'screen-el screen-' + type;
  d.id = 'el-' + id;
  d.dataset.id = id;
  d.dataset.type = type;
  d.dataset.text = text;
  d.dataset.desc = desc;
  d.style.left = x + 'px';
  d.style.top = y + 'px';
  d.style.width = w + 'px';
  d.style.height = h + 'px';
  d.style.background = color || 'transparent';
  d.textContent = text;
  d.title = desc || text;
  d.addEventListener('click', (ev) => {
    ev.stopPropagation();
    onElementTap(id);
  });
  return d;
}
function btnEl(id, text, x, y, w, h, onTap, { kind = 'primary', desc = '' } = {}) {
  const d = el(id, 'button', text, x, y, w, h, { desc, onclick: onTap });
  d.classList.add('screen-btn', 'btn-' + kind);
  return d;
}
function fieldEl(id, text, x, y, w, h, { desc = '', value = '' } = {}) {
