function renderCalculator() {
  screen.appendChild(btnEl('navHome', '⌂ Home', 16, 44, 70, 36, () => { phoneHome(); }, { kind: 'ghost' }));
  const disp = fieldEl('calcDisplay', '', 16, 100, 343, 60, { value: state.calcValue || '0' });
