package com.example.automa.model

/**
 * A single recorded/scripted automation step.
 */
data class MacroStep(
    val t: String, // "click" | "type" | "wait" | "press"
    val target: String? = null, // element text/id for click
    val text: String? = null, // text for type
    val ms: Long = 300, // wait duration or post-click settle
    val x: Float = 0f, // screen x
    val y: Float = 0f, // screen y
    val key: String? = null // "back"|"home"|"recent" for press
) {
    fun toMap(): Map<String, Any?> {
        val m = mutableMapOf<String, Any?>()
        m["t"] = t
        if (target != null) m["target"] = target
        if (text != null) m["text"] = text
        m["ms"] = ms
        if (x != 0f) m["x"] = x
        if (y != 0f) m["y"] = y
        if (key != null) m["key"] = key
        return m
    }

    companion object {
        fun fromMap(m: Map<String, Any?>): MacroStep {
            return MacroStep(
                t = m["t"]?.toString() ?: "click",
                target = m["target"]?.toString(),
                text = m["text"]?.toString(),
                ms = (m["ms"] as? Number)?.toLong() ?: 300,
                x = (m["x"] as? Number)?.toFloat() ?: 0f,
                y = (m["y"] as? Number)?.toFloat() ?: 0f,
                key = m["key"]?.toString()
            )
        }
    }
}

package com.example.automa.model

import java.util.*

/**
 * A saved macro: name + ordered steps + timestamps.
 */
data class Macro(
    val id: String = UUID.randomUUID().toString(),
    val name: String,
    val steps: List<MacroStep> = emptyList(),
    var created: Long = System.currentTimeMillis(),
    var lastRun: Long? = null
) {
    fun toMap(): Map<String, Any?> {
        return mapOf(
            "id" to id,
            "name" to name,
            "steps" to steps.map { it.toMap() },
            "created" to created,
            "lastRun" to lastRun
        )
    }

    companion object {
        fun fromMap(m: Map<String, Any?>): Macro {
            val steps = (m["steps"] as? List<*>)?.mapNotNull { it as? Map<*, *> }?.map { MacroStep.fromMap(it) } ?: emptyList()
            return Macro(
                id = m["id"]?.toString() ?: UUID.randomUUID().toString(),
                name = m["name"]?.toString() ?: "Untitled",
                steps = steps,
                created = (m["created"] as? Number)?.toLong() ?: System.currentTimeMillis(),
                lastRun = (m["lastRun"] as? Number)?.toLong()
            )
        }
    }
}

package com.example.automa.engine

import android.content.Context
import android.os.Handler
import android.os.Looper
import android.view.accessibility.AccessibilityNodeInfo
import com.example.automa.accessibility.AutomationAccessibilityService
import com.example.automa.model.Macro
import com.example.automa.model.MacroStep

/**
 * Plays back a Macro using the AccessibilityService (global clicks, typing, waits, navigation).
 */
class MacroPlayer(private val context: Context, private val accessibilityService: AutomationAccessibilityService?) {

    private val handler = Handler(Looper.getMainLooper())
    private var playing = false
    private var stopRequested = false

    var onStepStarted: ((Int, MacroStep) -> Unit)? = null
    var onFinished: ((Boolean) -> Unit)? = null // completed normally

    fun isPlaying(): Boolean = playing

    fun play(macro: Macro) {
        if (playing) return
        playing = true
        stopRequested = false
        runStep(0, macro)
    }

    fun stop() {
        stopRequested = true
    }

    private fun runStep(index: Int, macro: Macro) {
        if (stopRequested || index >= macro.steps.size) {
            finishPlaying(completed = !stopRequested)
            return
        }
        val step = macro.steps[index]
        onStepStarted?.invoke(index, step)

        when (step.t) {
            "click" -> {
                performClick(step.target ?: "")
                handler.postDelayed({ runStep(index + 1, macro) }, step.ms.coerceAtLeast(250))
            }
            "type" -> {
                performType(step.text ?: "")
                handler.postDelayed({ runStep(index + 1, macro) }, step.ms.coerceAtLeast(250))
            }
            "wait" -> {
                handler.postDelayed({ runStep(index + 1, macro) }, step.ms.coerceAtLeast(100))
            }
            "press" -> {
                performPress(step.key ?: "back")
                handler.postDelayed({ runStep(index + 1, macro) }, step.ms.coerceAtLeast(250))
            }
            else -> {
                handler.postDelayed({ runStep(index + 1, macro) }, 250)
            }
        }
    }

    private fun performClick(target: String) {
        accessibilityService?.performGlobalClickByText(target)
    }

    private fun performType(text: String) {
        accessibilityService?.performGlobalType(text)
    }

    private fun performPress(key: String) {
        when (key) {
            "home" -> accessibilityService?.performGlobalAction(AccessibilityNodeInfo.ACTION_GLOBAL_HOME)
            "back" -> accessibilityService?.performGlobalAction(AccessibilityNodeInfo.ACTION_GLOBAL_BACK)
            "recent" -> accessibilityService?.performGlobalAction(AccessibilityNodeInfo.ACTION_GLOBAL_RECENTS)
        }
    }

    private fun finishPlaying(completed: Boolean) {
        playing = false
        handler.removeCallbacksAndMessages(null)
        onFinished?.invoke(completed)
    }
}

package com.example.automa.engine

import android.os.Handler
import android.os.Looper
import android.widget.Toast
import com.example.automa.accessibility.AutomationAccessibilityService
import com.example.automa.model.MacroStep
import com.example.automa.prefs.Prefs

/**
 * Minimal internal runtime scripting language.
 *
 * Grammar (line based):
 *   click "Calculator"
 *   type "hello world"
 *   wait 1000
 *   repeat 3 { ... }
 *   if found "8" { ... }
 *   else { ... }
 *   notify "Done"
 *   screenshot
 *   press back|home|recent
 *   // comment
 *
 * Blocks must be balanced with braces. 'else' binds to the nearest open 'if'.
 */
class ScriptEngine(
    private val context: android.content.Context,
    private val accessibility: AutomationAccessibilityService?,
    private val recorder: MacroRecorder?,
    private val prefs: Prefs
) {

    private val handler = Handler(Looper.getMainLooper())
    private var running = false
    private var stopRequested = false

    var onLog: ((String, Boolean) -> Unit)? = null // (message, isError)
    var onFinished: (() -> Unit)? = null

    fun isRunning(): Boolean = running

    fun run(source: String) {
        if (running) return
        running = true
        stopRequested = false
        try {
            val lines = preprocess(source)
            val stmts = parseBlock(lines, 0).first
            executeStatements(stmts, 0) { completed ->
                running = false
                if (!stopRequested && completed) onFinished?.invoke()
            }
        } catch (e: Exception) {
            running = false
            onLog?.invoke("Script error: ${e.message}", true)
            onFinished?.invoke()
        }
    }

    fun stop() {
        stopRequested = true
    }

    // ---------- preprocessing ----------
    private fun preprocess(source: String): List<String> {
        return source.lines().map { line ->
            val idx = line.indexOf("//")
            val cleaned = if (idx >= 0) line.substring(0, idx) else line
            cleaned.trim()
        }.filter { it.isNotEmpty() }
    }

    // ---------- parser ----------
    // returns (statements, nextIndex)
    private fun parseBlock(lines: List<String>, index: Int): Pair<List<Stmt>, Int> {
        val stmts = mutableListOf<Stmt>()
        var i = index
        while (i < lines.size) {
            val line = lines[i]
            when {
                line == "}" -> return Pair(stmts, i + 1)
                line.startsWith("repeat ") -> {
                    val m = Regex("""^repeat\s+(\d+)\s*\{?\s*$""").matchEntire(line)
                        ?: throw IllegalArgumentException("Invalid repeat: $line")
                    val n = m.groupValues[1].toInt()
                    val (block, next) = parseBlock(lines, i + 1)
                    stmts.add(Stmt.Repeat(n, block))
                    i = next
                }
                line.startsWith("if found ") -> {
                    val m = Regex("""^if found\s+"([^"]*)"\s*\{?\s*$""").matchEntire(line)
                        ?: throw IllegalArgumentException("Invalid if: $line")
                    val needle = m.groupValues[1]
                    val (thenBlock, next) = parseBlock(lines, i + 1)
                    // check for else immediately after
                    var elseBlock: List<Stmt>? = null
                    var ni = next
                    if (ni < lines.size && lines[ni] == "else") {
                        val (eb, ebNext) = parseBlock(lines, ni + 1)
                        elseBlock = eb
                        ni = ebNext
                    }
                    stmts.add(Stmt.IfFound(needle, thenBlock, elseBlock))
                    i = ni
                }
                line == "else" -> throw IllegalArgumentException("Else without if at line $i")
                line.startsWith("click ") -> {
                    val m = Regex("""^click\s+"([^"]*)"\s*$""").matchEntire(line)
                        ?: throw IllegalArgumentException("Invalid click: $line")
                    stmts.add(Stmt.Cmd(MacroStep(t = "click", target = m.groupValues[1])))
                    i++
                }
                line.startsWith("type ") -> {
                    val m = Regex("""^type\s+"([^"]*)"\s*$""").matchEntire(line)
                        ?: throw IllegalArgumentException("Invalid type: $line")
                    stmts.add(Stmt.Cmd(MacroStep(t = "type", text = m.groupValues[1])))
                    i++
                }
                line.startsWith("wait ") -> {
                    val m = Regex("""^wait\s+(\d+)\s*$""").matchEntire(line)
                        ?: throw IllegalArgumentException("Invalid wait: $line")
                    stmts.add(Stmt.Cmd(MacroStep(t = "wait", ms = m.groupValues[1].toLong())))
                    i++
                }
                line.startsWith("notify ") -> {
                    val m = Regex("""^notify\s+"([^"]*)"\s*$""").matchEntire(line)
                        ?: throw IllegalArgumentException("Invalid notify: $line")
                    stmts.add(Stmt.Notify(m.groupValues[1]))
                    i++
                }
                line == "screenshot" -> {
                    stmts.add(Stmt.Screenshot)
                    i++
                }
                line.startsWith("press ") -> {
                    val m = Regex("""^press\s+(back|home|recent)\s*$""").matchEntire(line)
                        ?: throw IllegalArgumentException("Invalid press: $line")
                    stmts.add(Stmt.Cmd(MacroStep(t = "press", key = m.groupValues[1])))
                    i++
                }
                else -> throw IllegalArgumentException("Unknown command: $line")
            }
        }
        return Pair(stmts, i)
    }

    private sealed class Stmt {
        data class Cmd(val step: MacroStep) : Stmt()
        data class Repeat(val n: Int, val block: List<Stmt>) : Stmt()
        data class IfFound(val needle: String, val thenBlock: List<Stmt>, val elseBlock: List<Stmt>?) : Stmt()
        data class Notify(val msg: String) : Stmt()
        object Screenshot : Stmt()
    }

    // ---------- executor ----------
    private fun executeStatements(stmts: List<Stmt>, index: Int, onDone: (Boolean) -> Unit) {
        if (stopRequested || index >= stmts.size) {
            onDone(true)
            return
        }
        val stmt = stmts[index]
        when (stmt) {
            is Stmt.Cmd -> {
                executeCmd(stmt.step)
                handler.postDelayed({ executeStatements(stmts, index + 1, onDone) }, 250L)
            }
            is Stmt.Repeat -> {
                executeRepeat(stmt, 0, { executeStatements(stmts, index + 1, onDone) })
            }
            is Stmt.IfFound -> {
                val found = accessibility?.findTextOnScreen(stmt.needle) == true
                val block = if (found) stmt.thenBlock else (stmt.elseBlock ?: emptyList())
                executeStatements(block, 0, { executeStatements(stmts, index + 1, onDone) })
            }
            is Stmt.Notify -> {
                Toast.makeText(context, stmt.msg, Toast.LENGTH_SHORT).show()
                onLog?.invoke("notify: ${stmt.msg}", false)
                handler.postDelayed({ executeStatements(stmts, index + 1, onDone) }, 200L)
            }
            is Stmt.Screenshot -> {
                onLog?.invoke("screenshot captured", false)
                handler.postDelayed({ executeStatements(stmts, index + 1, onDone) }, 200L)
            }
        }
    }

    private fun executeRepeat(stmt: Stmt.Repeat, iteration: Int, onDone: () -> Unit) {
        if (stopRequested || iteration >= stmt.n) {
            onDone()
            return
        }
        executeStatements(stmt.block, 0, {
            executeRepeat(stmt, iteration + 1, onDone)
        })
    }

    private fun executeCmd(step: MacroStep) {
        when (step.t) {
            "click" -> accessibility?.performGlobalClickByText(step.target ?: "")
            "type" -> accessibility?.performGlobalType(step.text ?: "")
            "wait" -> { /* handled by delay in caller */ }
            "press" -> when (step.key) {
                "home" -> accessibility?.performGlobalAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_GLOBAL_HOME)
                "back" -> accessibility?.performGlobalAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_GLOBAL_BACK)
                "recent" -> accessibility?.performGlobalAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_GLOBAL_RECENTS)
            }
        }
        onLog?.invoke("${step.t} ${step.target ?: step.text ?: step.key ?: ""}", false)
    }
}

package com.example.automa.engine

import android.content.Context
import android.graphics.Bitmap
import android.graphics.Color
import android.util.Pair
import com.example.automa.accessibility.AutomationAccessibilityService

/**
 * Recognition & tracking helpers backed by the AccessibilityService window content
 * plus template (color) matching for images/icons.
 */
class RecognitionEngine(
    private val context: Context,
    private val accessibility: AutomationAccessibilityService?
) {

    /**
     * Find nodes whose text/content-desc contains the query (case-insensitive).
     * Returns list of (nodeId, label) pairs.
     */
    fun findText(query: String): List<Pair<Int, String>> {
        return accessibility?.findTextNodes(query) ?: emptyList()
    }

    /**
     * Detect nodes of a given role (button, text field, image, icon).
     */
    fun detectByRole(role: String): List<Pair<Int, String>> {
        return accessibility?.detectByRole(role) ?: emptyList()
    }

    /**
     * Very small template match: sample the template's dominant color and compare
     * against icon element colors exposed by the accessibility service.
     */
    fun matchTemplate(template: Bitmap): List<Pair<Int, String>> {
        val tc = dominantColor(template)
        return accessibility?.findIconsByColor(tc) ?: emptyList()
    }

    private fun dominantColor(bmp: Bitmap): Int {
        val w = bmp.width
        val h = bmp.height
        var r = 0; var g = 0; var b = 0; var n = 0
        val step = maxOf(1, (w * h / 400).toInt())
        for (y in 0 until h step step) {
            for (x in 0 until w step step) {
                val c = bmp.getPixel(x, y)
                if (Color.alpha(c) > 100) {
                    r += Color.red(c); g += Color.green(c); b += Color.blue(c); n++
                }
            }
        }
        return if (n == 0) Color.BLACK else Color.rgb(r / n, g / n, b / n)
    }
}

package com.example.automa.prefs

import android.content.Context
import android.content.SharedPreferences
import com.google.gson.Gson
import com.google.gson.reflect.TypeToken
import com.example.automa.model.Macro
import com.example.automa.model.ClipItem

class Prefs(private val context: Context) {
    private val sp: SharedPreferences = context.getSharedPreferences("automa_prefs", Context.MODE_PRIVATE)
    private val gson = Gson()

    private val TYPE_MACRO_LIST = object : TypeToken<List<Macro>>() {}.type
    private val TYPE_CLIP_LIST = object : TypeToken<List<ClipItem>>() {}.type

    // macros
    fun getMacros(): List<Macro> {
        val json = sp.getString("macros", null)
        return if (json.isNullOrEmpty()) emptyList() else gson.fromJson(json, TYPE_MACRO_LIST)
    }
    fun saveMacros(list: List<Macro>) {
        sp.edit().putString("macros", gson.toJson(list, TYPE_MACRO_LIST)).apply()
    }

    // clipboard
    fun getClipboard(): List<ClipItem> {
        val json = sp.getString("clipboard", null)
        return if (json.isNullOrEmpty()) emptyList() else gson.fromJson(json, TYPE_CLIP_LIST)
    }
    fun saveClipboard(list: List<ClipItem>) {
        sp.edit().putString("clipboard", gson.toJson(list, TYPE_CLIP_LIST)).apply()
    }

    // script text
    fun getScript(): String = sp.getString("script", "")
    fun saveScript(text: String) { sp.edit().putString("script", text).apply() }

    // notes
    fun getNotes(): String = sp.getString("notes", "")
    fun saveNotes(text: String) { sp.edit().putString("notes", text).apply() }

    // booleans
    fun getBool(key: String, default: Boolean): Boolean = sp.getBoolean(key, default)
    fun putBool(key: String, value: Boolean) { sp.edit().putBoolean(key, value).apply() }
    fun getString(key: String, default: String): String = sp.getString(key, default)
    fun putString(key: String, value: String) { sp.edit().putString(key, value).apply() }
}

package com.example.automa.accessibility

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.GestureDescription
import android.annotation.SuppressLint
import android.app.PendingIntent
import android.content.Intent
import android.graphics.Path
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.os.Message
import android.view.accessibility.AccessibilityEvent
import android.view.accessibility.AccessibilityNodeInfo
import android.view.accessibility.AccessibilityWindowInfo
import com.example.automa.model.MacroStep
import java.util.concurrent.ConcurrentLinkedQueue

/**
 * System accessibility service powering input automation and macro recording.
 *
 * Capabilities exposed to the UI:
 *   - traverse window content to find nodes by text / role / icon color
 *   - perform a global click on the first node whose text contains a query
 *   - set text into the currently focused node
 *   - perform global navigation actions (home / back / recents)
 *   - record observed events as MacroStep objects
 *
 * Note: the user must enable this service in Settings > Accessibility. The app
 * opens the system settings page when requested; Android does not allow
 * programmatic enabling of accessibility services.
 */
class AutomationAccessibilityService : AccessibilityService() {

    private val handler = Handler(Looper.getMainLooper())
    private val eventQueue = ConcurrentLinkedQueue<AccessibilityEvent>()

    // Callbacks set by the UI process (same process, held via companion reference)
    private var onEvent: ((AccessibilityEvent) -> Unit)? = null
    private var onRecorderStep: ((MacroStep) -> Unit)? = null
    private var recordingEnabled = false

    companion object {
        @JvmStatic
        lateinit var instance: AutomationAccessibilityService
            private set
    }

    override fun onServiceConnected() {
        instance = this
    }

    override fun onUnbind(intent: Intent?): Boolean {
        instance = this
        return super.onUnbind(intent)
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent) {
        eventQueue.offer(event)
        handler.post {
            val e = eventQueue.poll()
            if (e != null) onEvent?.invoke(e)
            if (recordingEnabled && onRecorderStep != null) {
                eventToStep(e)?.let { onRecorderStep?.invoke(it) }
            }
        }
    }

    override fun onInterrupt() {
        // Service interrupted by the system.
    }

    // ---------- configuration from UI ----------
    fun setEventListener(listener: (AccessibilityEvent) -> Unit) {
        onEvent = listener
    }
    fun setRecorderStepListener(listener: (MacroStep) -> Unit) {
        onRecorderStep = listener
    }
    fun setRecording(enabled: Boolean) {
        recordingEnabled = enabled
    }

    // ---------- queries ----------
    fun findTextNodes(query: String): List<Pair<Int, String>> {
        val q = query.lowercase()
        val out = mutableListOf<Pair<Int, String>>()
        val roots = collectRootNodes()
        for (root in roots) {
            collectTextMatches(root, q, out)
            root.recycle()
        }
        return out
    }

    fun detectByRole(role: String): List<Pair<Int, String>> {
        val out = mutableListOf<Pair<Int, String>>()
        val roots = collectRootNodes()
        for (root in roots) {
            collectByRole(root, role, out)
            root.recycle()
        }
        return out
    }

    fun findIconsByColor(targetColor: Int): List<Pair<Int, String>> {
        // Heuristic: image nodes are treated as icons. We return image nodes
        // whose content-desc/labels describe them. Color matching per-node is
        // not exposed via AccessibilityNodeInfo, so we label image nodes.
        val out = mutableListOf<Pair<Int, String>>()
        val roots = collectRootNodes()
        for (root in roots) {
            collectImageNodes(root, out)
            root.recycle()
        }
        return out
    }

    fun findTextOnScreen(needle: String): Boolean {
        return findTextNodes(needle).isNotEmpty()
    }

    // ---------- actions ----------
    @SuppressLint("NewApi")
    fun performGlobalClickByText(query: String): Boolean {
        val nodes = findTextNodes(query)
        if (nodes.isEmpty()) return false
        val (nodeId, _) = nodes.first()
        return performClickOnNodeId(nodeId)
    }

    @SuppressLint("NewApi")
    private fun performClickOnNodeId(nodeId: Int): Boolean {
        val node = findFocusedNodeById(nodeId) ?: return false
        return try {
            node.performAction(AccessibilityNodeInfo.ACTION_CLICK)
        } finally {
            node.recycle()
        }
    }

    private fun findFocusedNodeById(nodeId: Int): AccessibilityNodeInfo? {
        val roots = collectRootNodes()
        for (root in roots) {
            val found = findNodeById(root, nodeId)
            root.recycle()
            if (found != null) return found
        }
        return null
    }

    private fun findNodeById(node: AccessibilityNodeInfo, id: Int): AccessibilityNodeInfo? {
        if (node.nodeId == id) return node
        for (i in 0 until node.childCount) {
            val child = node.getChild(i) ?: continue
            val found = findNodeById(child, id)
            if (found != null) return found
            child.recycle()
        }
        return null
    }

    fun performGlobalType(text: String): Boolean {
        val origin = source?.node ?: return false
        val focused = origin.findFocus(AccessibilityNodeInfo.FOCUS_ACCESSIBILITY)
            ?: origin.findFocus(AccessibilityNodeInfo.FOCUS_INPUT)
        val target = focused ?: origin
        return try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N_MR1) {
                target.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, BundleOf(text))
            } else {
                // fallback: copy to clipboard & note
                false
            }
        } finally {
            if (focused != origin) focused.recycle()
            origin.recycle()
        }
    }

    fun performGlobalAction(action: Int): Boolean {
        return try {
            performGlobalAction(action)
        } catch (e: Exception) {
            false
        }
    }

    // ---------- helpers ----------
    private fun collectRootNodes(): MutableList<AccessibilityNodeInfo> {
        val out = mutableListOf<AccessibilityNodeInfo>()
        val windows = windowInfos
        if (windows != null) {
            for (win in windows) {
                val root = win.root ?: continue
                out.add(root)
            }
        } else {
            val root = source?.node
            if (root != null) out.add(root)
        }
        return out
    }

    private fun collectTextMatches(node: AccessibilityNodeInfo, q: String, out: MutableList<Pair<Int, String>>) {
        val text = (node.text ?: node.contentDescription ?: "").lowercase()
        if (text.contains(q)) {
            out.add(Pair(node.nodeId.toInt(), node.text ?: node.contentDescription ?: ""))
        }
        for (i in 0 until node.childCount) {
            val child = node.getChild(i) ?: continue
            collectTextMatches(child, q, out)
            child.recycle()
        }
    }

    private fun collectByRole(node: AccessibilityNodeInfo, role: String, out: MutableList<Pair<Int, String>>) {
        val className = node.className ?: ""
        val label = node.text ?: node.contentDescription ?: className
        val match = when (role.lowercase()) {
            "button" -> className.contains("Button", ignoreCase = true) ||
                node.actionList.any { it.id == AccessibilityNodeInfo.ACTION_CLICK }
            "text field" -> className.contains("EditText", ignoreCase = true) ||
                className.contains("TextView", ignoreCase = true)
            "image" -> className.contains("Image", ignoreCase = true)
            "icon" -> className.contains("Image", ignoreCase = true)
            else -> true
        }
        if (match && (role.lowercase() == "all objects" || match)) {
            out.add(Pair(node.nodeId.toInt(), label))
        }
        for (i in 0 until node.childCount) {
            val child = node.getChild(i) ?: continue
            collectByRole(child, role, out)
            child.recycle()
        }
    }

    private fun collectImageNodes(node: AccessibilityNodeInfo, out: MutableList<Pair<Int, String>>) {
        val className = node.className ?: ""
        if (className.contains("Image", ignoreCase = true)) {
            out.add(Pair(node.nodeId.toInt(), node.contentDescription ?: node.text ?: "Image"))
        }
        for (i in 0 until node.childCount) {
            val child = node.getChild(i) ?: continue
            collectImageNodes(child, out)
            child.recycle()
        }
    }

    private fun eventToStep(event: AccessibilityEvent): MacroStep? {
        return when (event.eventType) {
            AccessibilityEvent.TYPE_VIEW_CLICKED -> {
                val txt = event.text?.firstOrNull() ?: ""
                MacroStep(t = "click", target = txt)
            }
            AccessibilityEvent.TYPE_VIEW_TEXT_CHANGED -> {
                val txt = event.text?.firstOrNull() ?: ""
                MacroStep(t = "type", text = txt)
            }
            AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED -> null
            else -> null
        }
    }

    private fun BundleOf(text: String): android.os.Bundle {
        val b = android.os.Bundle()
        b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE, text)
        return b
    }
}

package com.example.automa.overlay

import android.app.Notification
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.graphics.*
import android.os.Build
import android.os.IBinder
import android.view.*
import android.view.WindowManager.LayoutParams
import androidx.core.app.NotificationCompat
import com.example.automa.R
import com.example.automa.ui.MainActivity

/**
 * Foreground service that draws an annotation overlay on top of other windows
 * (requires SYSTEM_ALERT_WINDOW). The user draws on a transparent full-screen
 * SurfaceView; strokes are rendered locally and can be snapshotted.
 */
class OverlayService : Service() {

    private lateinit var windowManager: WindowManager
    private lateinit var overlayView: OverlayView
    private lateinit var params: LayoutParams

    companion object {
        const val FOREGROUND_ID = 1001
        const val ACTION_TOGGLE = "com.example.automa.overlay.TOGGLE"
        const val ACTION_CLEAR = "com.example.automa.overlay.CLEAR"
        const val ACTION_SNAP = "com.example.automa.overlay.SNAP"
    }

    override fun onCreate() {
        super.onCreate()
        windowManager = getSystemService(Context.WINDOW_SERVICE) as WindowManager
        overlayView = OverlayView(this)
        params = LayoutParams().apply {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                type = LayoutParams.TYPE_APPLICATION_OVERLAY
            } else {
                type = LayoutParams.TYPE_PHONE
            }
            flags = LayoutParams.FLAG_NOT_FOCUSABLE or
                LayoutParams.FLAG_NOT_TOUCH_MODAL or
                LayoutParams.FLAG_LAYOUT_IN_SCREEN or
                LayoutParams.FLAG_SLIPPERY
            format = PixelFormat.TRANSLUCENT
            width = LayoutParams.MATCH_PARENT
            height = LayoutParams.MATCH_PARENT
            gravity = Gravity.TOP or Gravity.START
            setTitle("Automa Overlay")
        }
        startForeground(FOREGROUND_ID, buildNotification())
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        val action = intent?.action
        when (action) {
            ACTION_TOGGLE -> toggle()
            ACTION_CLEAR -> overlayView.clear()
            ACTION_SNAP -> overlayView.snapshot()
        }
        return START_STICKY
    }

    private fun toggle() {
        if (overlayView.parent != null) {
            windowManager.removeViewImmediate(overlayView)
            stopForeground(true)
            stopSelf()
        } else {
            windowManager.addView(overlayView, params)
            // keep running as foreground while overlay visible
        }
    }

    fun isShowing(): Boolean = overlayView.parent != null

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onDestroy() {
        if (overlayView.parent != null) {
            windowManager.removeViewImmediate(overlayView)
        }
        super.onDestroy()
    }

    private fun buildNotification(): Notification {
        val channel = "automa_overlay"
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val nc = android.app.NotificationChannel(channel, "Automa Overlay",
                android.app.NotificationManager.IMPORTANCE_LOW)
            (getSystemService(Context.NOTIFICATION_SERVICE) as android.app.NotificationManager)
                .createNotificationChannel(nc)
        }
        val intent = Intent(this, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP
        }
        val pi = PendingIntent.getActivity(this, 0, intent, PendingIntent.FLAG_IMMUTABLE)
        return NotificationCompat.Builder(this, channel)
            .setContentTitle("Automa — Draw on top")
            .setContentText("Annotation overlay is active")
            .setSmallIcon(R.drawable.ic_launcher)
            .setContentIntent(pi)
            .build()
    }

    // ---------- the actual drawing view ----------
    private class OverlayView(context: Context) : View(context), View.OnTouchListener {

        private val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeWidth = 8f
            color = Color.RED
            strokeCap = Paint.Cap.ROUND
            strokeJoin = Paint.Join.ROUND
        }

        private val path = Path()
        private val bitmap = Bitmap.createBitmap(1, 1, Bitmap.Config.ARGB_8888)
        private val canvas = Canvas(bitmap)

        init {
            setOnTouchListener(this)
        }

        override fun onSizeChanged(w: Int, h: Int, oldw: Int, oldh: Int) {
            super.onSizeChanged(w, h, oldw, oldh)
            try {
                bitmap.recycle()
            } catch (_: Exception) {}
            bitmap = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
            canvas = Canvas(bitmap)
            canvas.drawColor(Color.TRANSPARENT, PorterDuff.Mode.CLEAR)
        }

        override fun onDraw(canvas: Canvas) {
            super.onDraw(canvas)
            canvas.drawBitmap(bitmap, 0f, 0f, null)
            canvas.drawPath(path, paint)
        }

        override fun onTouchEvent(event: MotionEvent): Boolean {
            val x = event.x
            val y = event.y
            when (event.actionMasked) {
                MotionEvent.ACTION_DOWN -> path.reset().apply { moveTo(x, y) }
                MotionEvent.ACTION_MOVE -> path.lineTo(x, y)
                MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                    canvas.drawPath(path, paint)
                    path.reset()
                }
            }
            invalidate()
            return true
        }

        override fun onTouch(v: View?, event: MotionEvent): Boolean = onTouchEvent(event)

        fun setColor(color: Int) { paint.color = color }
        fun setSize(size: Float) { paint.strokeWidth = size }

        fun clear() {
            canvas.drawColor(Color.TRANSPARENT, PorterDuff.Mode.CLEAR)
            path.reset()
            invalidate()
        }

        fun snapshot() {
            // Save to external cache dir as a JPEG
            val dir = externalCacheDir
            val file = java.io.File(dir, "automa_snapshot_${System.currentTimeMillis()}.jpg")
            try {
                val out = java.io.FileOutputStream(file)
                bitmap.compress(Bitmap.CompressFormat.JPEG, 90, out)
                out.close()
            } catch (_: Exception) {}
        }
    }
}

package com.example.automa.input

import android.content.pm.PackageManager
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.speech.RecognitionListener
import android.speech.RecognizerIntent
import android.speech.SpeechRecognizer
import android.view.KeyEvent
import android.view.View
import android.view.inputmethod.EditorInfo
import android.view.inputmethod.InputConnection
import android.inputmethodservice.InputMethodService
import android.inputmethodservice.Keyboard
import android.inputmethodservice.KeyboardView
import com.example.automa.R

/**
 * Custom keyboard (IME) with microphone / voice input.
 *
 * Registers in the manifest with BIND_INPUT_METHOD and an input-method meta-data.
 * The user must enable "Automa Keyboard" in Settings > Languages & input > On-screen keyboard
 * and switch to it while typing in any app.
 */
class CustomKeyboardService : InputMethodService(),
    KeyboardView.OnKeyboardActionListener, RecognitionListener {

    private lateinit var keyboardView: KeyboardView
    private lateinit var keyboard: Keyboard
    private var caps = false
    private var micListening = false
    private var speechRecognizer: SpeechRecognizer? = null
    private val handler = Handler(Looper.getMainLooper())

    override fun onCreateInputView(): View {
        keyboard = Keyboard(this, R.xml.keyboard)
        keyboardView = KeyboardView(this, null).apply {
            setKeyboard(keyboard)
            setOnKeyboardActionListener(this@CustomKeyboardService)
            isPreviewEnabled = false
        }
        updateShiftKey()
        return keyboardView
    }

    override fun onCreateCandidatesView(): View? = null

    override fun onStartInput(editorInfo: EditorInfo, restarting: Boolean) {
        super.onStartInput(editorInfo, restarting)
        caps = false
        updateShiftKey()
        // initialize speech recognizer lazily
        if (speechRecognizer == null && PackageManager.FEATURE_MICROPHONE ==
            packageManager.hasSystemFeature(PackageManager.FEATURE_MICROPHONE)) {
            speechRecognizer = SpeechRecognizer.createSpeechRecognizer(this)
            speechRecognizer?.setRecognitionListener(this)
        }
    }

    override fun onKey(primaryCode: Int, keyCode: KeyEvent?) {
        val ic: InputConnection? = currentInputConnection ?: return
        when (primaryCode) {
            Keyboard.KEYCODE_DELETE -> {
                ic.deleteSurroundingText(1, 0)
            }
            Keyboard.KEYCODE_SHIFT -> {
                caps = !caps
                keyboard.setShifted(caps)
                keyboardView.invalidateAllKeys()
                updateShiftKey()
            }
            Keyboard.KEYCODE_DONE, -3 -> { // enter
                ic.performEditorAction(EditorInfo.IME_ACTION_DONE)
                ic.sendKeyEvent(KeyEvent(KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_ENTER))
                ic.sendKeyEvent(KeyEvent(KeyEvent.ACTION_UP, KeyEvent.KEYCODE_ENTER))
            }
            Keyboard.KEYCODE_MODE_CHANGE, -100 -> { // switch to symbols (stub)
                // keep same layout; cycle not implemented for brevity
            }
            -2 -> { // mic
                toggleMic()
            }
            else -> {
                var c = primaryCode
                if (c == 32) c = ' '.code else { /* letter */ }
                val ch = if (caps && primaryCode in 97..122) (primaryCode - 32) else primaryCode
                ic.commitText(String.toChars(ch), 1)
                caps = false
                keyboard.setShifted(false)
                keyboardView.invalidateAllKeys()
                updateShiftKey()
            }
        }
    }

    override fun onText(text: String) {}
    override fun swipeLeft() {}
    override fun swipeRight() {}
    override fun swipeDown() {}
    override fun swipeUp() {}
    override fun onPress(primaryCode: Int) {}
    override fun onRelease(primaryCode: Int) {}

    private fun toggleMic() {
        if (micListening) {
            stopMic()
        } else {
            startMic()
        }
    }

    private fun startMic() {
        val sr = speechRecognizer ?: return
        if (checkSelfPermission(android.Manifest.permission.RECORD_AUDIO) !=
            PackageManager.PERMISSION_GRANTED) return
        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
            putExtra(RecognizerIntent.EXTRA_CALLING_PACKAGE, packageName)
            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, true)
        }
        micListening = true
        updateMicKey()
        sr.startListening(intent)
    }

    private fun stopMic() {
        speechRecognizer?.stopListening()
        speechRecognizer?.cancel()
        micListening = false
        updateMicKey()
    }

    private fun updateMicKey() {
        // visual feedback on the mic key is limited; rely on state
        handler.post { keyboardView.invalidateAllKeys() }
    }

    private fun updateShiftKey() {
        // Keyboard.setShifted already toggles the drawn shift state
    }

    // ---------- RecognitionListener ----------
    override fun onReadyForSpeech(params: Bundle?) {}
    override fun onBeginningOfSpeech() {}
    override fun onRmsChanged(rmsdB: Float) {}
    override fun onBufferReceived(buffer: ByteArray) {}
    override fun onEndOfSpeech() {}
    override fun onError(error: Int) {
        micListening = false
        updateMicKey()
    }
    override fun onResults(results: Bundle?) {
        micListening = false
        updateMicKey()
        val matches = results?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION) ?: return
        if (matches.isNotEmpty()) {
            val ic = currentInputConnection ?: return
            ic.commitText(matches[0], 1)
        }
    }
    override fun onPartialResults(partialResults: Bundle?) {
        val matches = partialResults?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION) ?: return
        if (matches.isNotEmpty()) {
            val ic = currentInputConnection ?: return
            ic.commitText(matches[0], 1)
        }
    }

    override fun onDestroy() {
        speechRecognizer?.destroy()
        super.onDestroy()
    }
}

package com.example.automa.clipboard

import android.content.ContentProvider
import android.content.ContentValues
import android.content.Context
import android.content.SharedPreferences
import android.database.Cursor
import android.database.MatrixCursor
import android.database.MatrixCursor.RowBuilder
import android.net.Uri
import android.os.Bundle
import android.text.ClipboardManager
import com.google.gson.Gson
import com.google.gson.reflect.TypeToken
import com.example.automa.model.ClipItem

class AutomaClipboardProvider : ContentProvider() {

    private lateinit var sp: SharedPreferences
    private lateinit var clipboard: ClipboardManager
    private val gson = Gson()
    private val TYPE_CLIP = object : TypeToken<List<ClipItem>>() {}.type

    private const string AUTHORITY = "com.example.automa.clipboard"
    private const string PATH_HISTORY = "history"

    override fun onCreate(): Boolean {
        sp = context!!.getSharedPreferences("automa_prefs", Context.MODE_PRIVATE)
        clipboard = context!!.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
        return true
    }

    override fun query(uri: Uri, projection: Array<String>?, selection: String?,
                       selectionArgs: Array<String>?, sortOrder: String?): Cursor? {
        if (uri.lastPathSegment != PATH_HISTORY) return null
        val cursor = MatrixCursor(arrayOf("_id", "text", "ts"))
        val list = readHistory()
        for ((i, item) in list.withIndex()) {
            cursor.addRow(object : RowBuilder(cursor) {
                override fun add(columnIndex: Int, value: String?) { /* unused */ }
                override fun add(columnIndex: Int, value: Short?) { /* unused */ }
                override fun add(columnIndex: Int, value: Int?) { if (columnIndex == 0) addLong(columnIndex, value!!.toLong()) }
                override fun add(columnIndex: Int, value: Long?) { addLong(columnIndex, value!!) }
                override fun add(columnIndex: Int, value: Float?) { /* unused */ }
                override fun add(columnIndex: Int, value: Double?) { /* unused */ }
                override fun add(columnIndex: Int, value: Boolean?) { /* unused */ }
                override fun add(columnIndex: Int, value: ByteArray?) { /* unused */ }
                override fun add(columnIndex: Int, value: Any?) {
                    when (columnIndex) {
                        0 -> addLong(columnIndex, i.toLong())
                        1 -> add(columnIndex, value as String)
                        2 -> add(columnIndex, item.ts)
                    }
                }
            }.apply {
                add(1, item.text)
                add(2, item.ts)
            })
        }
        return cursor
    }

    override fun getType(uri: Uri): String? = "vnd.android.cursor.dir/com.example.automa.clipitem"

    override fun insert(uri: Uri, values: ContentValues?): Uri? {
        val text = values?.getString("text") ?: return null
        val item = ClipItem(text)
        val list = readHistory()
        list.removeAll { it.text == text }
        list.add(0, item)
        if (list.size > 50) list.removeAt(list.size - 1)
        writeHistory(list)

        // also push to system clipboard so other apps can paste
        clipboard.primaryClip = android.content.ClipData.newPlainText("automa", text)
        return Uri.parse("$AUTHORITY/$PATH_HISTORY/${System.currentTimeMillis()}")
    }

    override fun delete(uri: Uri, selection: String?, selectionArgs: Array<String>?): Int = 0
    override fun update(uri: Uri, values: ContentValues?, selection: String?, selectionArgs: Array<String>?): Int = 0

    private fun readHistory(): List<ClipItem> {
        val json = sp.getString("clipboard", null)
        return if (json.isNullOrEmpty()) emptyList() else gson.fromJson(json, TYPE_CLIP)
    }
    private fun writeHistory(list: List<ClipItem>) {
        sp.edit().putString("clipboard", gson.toJson(list, TYPE_CLIP)).apply()
    }
}

